\label{main-theorem}
Let $(M,g_M)$ be a $n$-dimensional, compact, smooth, Riemannian manifold of positive $\sigma_2$--curvature (and in the positive $\Gamma_2^+$ cone), that is non-degenerate. Let $\Lambda$ be a subset of $M$ which is a closed, connected, submanifold of dimension $p$. Assume that
\begin{equation}\label{restriction-p}
0<p<\mathfrak p_2,
\end{equation}
where $\mathfrak p_2$ is given in  \eqref{exact-formulas} below. Then there exists an infinite dimensional family of solutions of \eqref{eq} in  $M\setminus\Lambda$, belonging to the positive $\Gamma_2^+$ cone, that are singular exactly on $\Lambda$. In particular, such solutions satisfy
\begin{equation}\label{asymptotic-behavior}
u(x)\sim \frac{1}{\operatorname{dist}(x,\Lambda)^{\frac{n-4}{4}}} \quad\text{as}\quad x\to\Lambda. 
\end{equation}

\cite{Gonzalez-Mazzieri}\label{ODE-study}
For each $0<p<\mathfrak p_2$, there exists a positive solution $U_1=U_1(r)$ for the equation
\begin{equation}\label{ODE-sigma2}
\sigma_2  \left( B_{g_{u}} \right)  = c u^{q}\quad\text{in}\quad\mathbb R^n\setminus\mathbb R^p,
\end{equation}
 satisfying:
\begin{itemize}
\item When $r\to 0$, the solution has the precise asymptotic behavior
$$U_1(r) \asymp v_\infty r^{-\frac{n-4}{4}}$$
where
\begin{equation}\label{v-infty}
(v_\infty)^{\frac{16}{n-4}}=c_{n,p,2}{\binom{n}{2}}^{-1}>0.
\end{equation}
and the constant $c_{n,p,2}$ is defined in \eqref{model-sigma-k}.

\item When $r\to +\infty$,
$$U_1(r) \asymp C r^{-\alpha_0-\frac{n-4}{4}}$$
for some $\alpha_0\in\left( 0,\frac{n-4}{4}\right)$, and some positive constant $C$.

\item $r^{\frac{n-4}{4}}U_1 $ is uniformly bounded for all $r>0$.

                                                                                                                                                                            
\item The metric $g_{U_1}:=(U_1)^{\frac{8}{n-4}} g_{E}$ belongs to the positive  $\Gamma_2^+$ cone.
\end{itemize}

\label{cor-model-solution}
For $\epsilon>0$ we rescale
\begin{equation}\label{rescale}U_\epsilon(r)=\epsilon^{-\frac{n-4}{4}}U_1\left(\frac{r}{\epsilon} \right). \end{equation}
Then
 $U_\epsilon$ is a solution of \eqref{eq} in $\mathbb R^n\setminus \mathbb R^p$ that only depends on the radial variable. Moreover, for $m$ large enough (independent of $\epsilon$),
\begin{equation}\label{behavior-zero}U_\epsilon(r)\asymp v_\infty \, r^{-\frac{n-4}{4}},\quad\text{when}\quad r\in\left(0,\tfrac{1}{m}\epsilon\right),\end{equation}
\begin{equation}\label{behavior-infty}
  U_\epsilon(r)\asymp C\epsilon^{\alpha_0} r^{-\alpha_0-\frac{n-4}{4}}\quad\text{when}\quad r\geq m\epsilon.
\end{equation}

\label{prop-gluing-Lambda}
 Let $g_0=u_0^{\frac{8}{n-4}}g_{M}$ be a smooth metric on a tubular neighborhood $\mathcal{T}_\rho$ of $\Lambda$ in $M$ satisfying $g_0\in \Gamma_2^+$. Fix  any $0<\alpha_1<\frac{n-4}{2}$. Then there exists a conformal metric $$g=u^{\frac{8}{n-4}}g_{M}\quad\text{on}\quad\mathcal T_\rho\setminus\{r=0\}$$
 that belongs to the positive $\Gamma_2^+$ cone  and satisfies the following:
\begin{align}
 & u(r,\theta,z) =u_0(r,\theta,z) \mbox{ in }\mathcal T_\rho\setminus \mathcal T_{\varrho_1}, \label{behavior-near}\\
  &u(r,\theta,z)=r^{-\alpha_1} \mbox{ in }\mathcal T_{\varrho}\setminus\{r=0\},\label{behavior-far}
\end{align}
for some $0<\varrho<\varrho_1<\rho$.
In addition, if $g_0$ is non-degenerate, then $g$ is also non-degenerate.

\label{prop:compare-metric}
For the error term we have the estimate
\begin{equation*}
\bar f_\epsilon=\begin{cases}
O(r),&\quad r\in (0,\frac{1}{m}\epsilon),\\
O(\epsilon),&\quad r\in (\frac{1}{m}\epsilon,m\epsilon),\\
O(\epsilon^{4\alpha_0} r^{-4\alpha_0+1}),&\quad r\in(m\epsilon,\varrho),\\
O(\epsilon^{4\alpha_0}),&\quad r>\varrho.
\end{cases}
\end{equation*}
The constants may depend on $m$ but not on $\epsilon$.

On the one hand, in the neighborhood $\mathcal T_\varrho$ we have defined $\bar v_\epsilon=V_\epsilon$, the model solution from Corollary \ref{cor-model-solution}. Observe that, in the model case  $\mathcal N(V_\epsilon, g_{cyl})\equiv 0$ from Proposition \ref{ODE-study}.
  In order to calculate the error $\mathcal N(V_\epsilon,g_{M,cyl})$ in this region we  compare the background metric $g_{M}$ in Fermi coordinates given in \eqref{metric-Fermi} to the model  $g_{E}$ from \eqref{metric-gE}  when $r\to 0$ as we did in the proof of Proposition \ref{prop-gluing-Lambda}
(one can also refer to the arguments in the proof of Proposition 2.19 of \cite{Mazzeo-Smale}).

On the other hand,  away from the singular set (say, $r>\varrho$), $\bar v_\epsilon$ is essentially a factor of $\epsilon^{\alpha_0}$ times a smooth function, thus we can calculate the error by keeping track of this rescaling in our
definition of the nonlinear operator.

With this we can conclude, with respect to the background metric $g_M$,
\begin{equation*}
B_{\bar g_v}=
\begin{cases}
B_{v_\infty,cyl}+O(r),&\quad r\in (0,\frac{1}{m}\epsilon),\\
B_{V_\epsilon,cyl}+O(r),&\quad r\in (\frac{1}{m}\epsilon,m\epsilon),\\
B_{V_1(-\log r+\log\epsilon),cyl}+O(V_\epsilon^2 r),&\quad r\in(m\epsilon,\varrho),\\
\epsilon^{2\alpha_0}B_{v_*,cyl}+O(v_*^2\,r),&\quad r\in(\varrho,\varrho_1),  \\
\epsilon^{2\alpha_0}B_{g_M},&\quad r>\varrho_1.
\end{cases}
\end{equation*}
Here we have denoted by $v_*$ the function $u_*$ with the normalization \eqref{change:uv}. Thus
\begin{equation*}
\sigma_2(B_{\bar g_v})=
\begin{cases}
cv_\infty^{q-1}+O(r),&\quad r\in (0,\frac{1}{m}\epsilon),\\
cV_\epsilon^{q-1}+O(r),&\quad r\in (\frac{1}{m}\epsilon,m\epsilon),\\
cV_1^{q}(-\log r+\log\epsilon)+O(V_\epsilon^4r),&\quad r\in(m\epsilon,\varrho),\\
O(\epsilon^{4\alpha_0}),&\quad r>\varrho,
\end{cases}
\end{equation*}
which yields the conclusion (recall the relation \eqref{V1-Vep}).

\label{lema:model-linearization}
The linearized operator for the model in cylindrical coordinates is given by
\begin{equation}\label{L-epsilon}
   L_\epsilon[w]=a_0^\epsilon w + a_1^\epsilon \partial_t w +a_2^\epsilon\partial_{tt} w+a_3^\epsilon\Delta_\theta w+a_4^\epsilon e^{-2t}\Delta_z w,
\end{equation}
where the coefficient functions $a_\ell^\epsilon=a_\ell^\epsilon(t)$ are given in the proof below. Moreover, $a^\epsilon_2,a^\epsilon_3,a^\epsilon_4$ have a sign, so this is an elliptic operator.

We follow the calculations in \cite{Mazzieri-Segatti} for the $\mathbb R^N\setminus\{0\}$ case. First
recall from \eqref{B-radial}, for $B_0(:=B_{g_{V_\epsilon}})$, that
\begin{equation}\label{B-radial2}\begin{split}
\big( B_{0}\big)_t^t & =    -\tfrac{n-2k}{4k} (V_\epsilon)^2  - V_\epsilon\ddot{V_\epsilon} +\tfrac{n-k}{n-2k}\dot{V_\epsilon}^2=:\kappa_1, \\
\big( B_{0}\big)_j^i & =  \left[\tfrac{n-2k}{4k}(V_\epsilon)^2-\tfrac{k}{n-2k} \dot{V_\epsilon}^2 \right] \delta_i^j =:\kappa_2\,\delta_i^j ,\\
\big( B_{0}\big)_\beta ^\alpha  & =   -\tfrac{n-2k}{4k}\big(V_\epsilon+\tfrac{2k}{n-2k}\,\dot V_\epsilon\big)^2 \delta_\beta ^\alpha =:\kappa_3\,\delta_\beta ^\alpha ,
\end{split}\end{equation}
and the rest of the entries of the matrix vanish. Moreover, for the diagonal matrix $B_0$,
\begin{equation}\label{S}\begin{split}
& [T^{k-1}(B_0)]_t^t= \sum_{m=0}^{k-1}(-1)^{k-1-m}\sigma_m(B_0)\kappa_1^{k-1-m}=:S_1,\\
&  [T^{k-1}(B_0)]_j^i= \left[\sum_{m=0}^{k-1}(-1)^{k-1-m}\sigma_m(B_0)\kappa_2^{k-1-m}\right]\delta_j^i=:S_2 \,\delta_i^j,\\
&  [T^{k-1}(B_0)]_\beta^\alpha= \left[\sum_{m=0}^{k-1}(-1)^{k-1-m}\sigma_m(B_0)\kappa_3^{k-1-m}\right]\delta_\beta^\alpha=:S_3\,\delta_\beta^\alpha.
\end{split}\end{equation}
 
Note that, since $g_{V_\epsilon}$ belongs to the positive  $\Gamma_k^+$ cone, then its $(k-1)$-Newton tensor $T^{k-1}$ is positive definite, so the quantities $S_1,S_2,S_3$ are strictly positive.
We recall from \eqref{Bs} that
\begin{equation*}\begin{split}
B_s&=\tfrac{n-2k}{2k}(V_\epsilon+sw)^2g_{cyl}^{-1}\,A_{g_{cyl}}-(V_\epsilon+sw)g_{cyl}^{-1}\,D^2(V_\epsilon+sw)\\
&+\tfrac{n}{n-2k}g_{cyl}^{-1}\,d(V_\epsilon+sw)\otimes d(V_\epsilon+sw)-\tfrac{k}{n-2k}|d(V_\epsilon+sw)|^2_{g_{cyl}}I,
\end{split}\end{equation*}
from where it is easy to calculate its variation:
\begin{equation*}
\begin{split}
\Big.\frac{d\big( B_{s}\big)_t^t}{ds}\Big|_{s=0} & =   -V_\epsilon \,\partial_{tt}w+\tfrac{2(n-k)}{n-2k}\, \dot V_
\epsilon\, (\partial_t w) - \left(\tfrac{n-2k}{2k} \,V_\epsilon+\ddot V_\epsilon\right)w, \\
\Big.\frac{d\big( B_{s}\big)_j^i}{ds}\Big|_{s=0} & =  -V_\epsilon \,g_\theta^{il}\,(D^2_\theta w)_{lj}-\tfrac{2k}{n-2k}\,\dot V_\epsilon \,\delta_j^i\,\partial_t w+\tfrac{n-2k}{2k}\,V_\epsilon\,\delta_j^i \,w,\\
\Big.\frac{d\big( B_{s}\big)_\beta ^\alpha}{ds}\Big|_{s=0} & =  -V_\epsilon\,e^{-2t} \partial_{\alpha\beta} w +\left[-\tfrac{2k}{n-2k} \,\dot V_\epsilon-V_\epsilon\right]\delta_\beta^\alpha\,\partial_t w\\&\quad+\left[-\tfrac{n-2k}{2k}\,V_\epsilon +\dot V_\epsilon\right]w\delta_\beta^\alpha.
\end{split}
\end{equation*}
                                                  
                  
                                                                                                                 
                                                                              
                                                                                                           
                      
                                                                                                                                        
                                                                                                                              
                               
                                                                                                                                                                                                      
                                                                                                        
                                                                                                                                                             
                                                                                                         
                                                                                                                                                                                                                                                    
                
Substituting \eqref{B-radial2} above one arrives at
\begin{equation*}\begin{split}
  \Big.\frac{d\big( B_{s}\big)_t^t}{ds}\Big|_{s=0} & =   (V_\epsilon)^{-1}\,(B_0)_t^t\,w -\tfrac{n-k}{n-2k}\,(V_\epsilon)^{-1}(\dot V_\epsilon)^2w-V_\epsilon\,\partial_{tt} w\\&\quad+\tfrac{2(n-k)}{n-2k}\dot V_\epsilon\partial_t w-\tfrac{n-2k}{4k}V_\epsilon w,\\
  \Big.\frac{d\big( B_{s}\big)_j^i}{ds}\Big|_{s=0} & =  (V_\epsilon)^{-1}\,w\, (B_0)_j^i+\tfrac{k}{n-2k}\,(V_{\epsilon})^{-1}(\dot V_\epsilon)^2 \,\delta_j^i\,w + \tfrac{n-2k}{4k}V_\epsilon \delta_j^i w\\&\quad-V_\epsilon (g_\theta)^{il} (D^2_\theta w)_{lj}
  -\tfrac{2k}{n-2k}\,\delta_j^i \,\dot V_\epsilon \,\partial_t w,   \\
  \Big.\frac{d\big( B_{s}\big)_\beta^\alpha}{ds}\Big|_{s=0} & =  (V_\epsilon)^{-1}\, w\,(B_0)_\beta^\alpha +\tfrac{k}{n-2k}\,(V_\epsilon)^{-1}(\dot V_\epsilon)^2 \delta_\beta^\alpha\,w-\tfrac{n-2k}{4k} V_\epsilon \delta_\beta^\alpha w \\&\quad+\left[-V_\epsilon-\tfrac{2k}{n-2k}\,\dot V_\epsilon\right]\delta_\beta^\alpha\,\partial_t w
  -V_\epsilon\, e^{-2t}\,\partial_{\alpha\beta} w.
  \end{split}
  \end{equation*}
Now, we can use the formula
$$k\sigma_k(B_0)=\operatorname{tr} \left(T^{k-1}(B_0)\cdot B_0\right),$$
to write
\begin{equation*}
\begin{split}
\Big.\frac{d}{ds}\Big|_{s=0}&\sigma_k(B_s)=k\sigma_k(B_0)\,(V_\epsilon)^{-1} w\\&+S_1\left[ -\tfrac{n-k}{n-2k}(V_\epsilon)^{-1} (\dot V_\epsilon)^2 w -\tfrac{n-2k}{4k}V_\epsilon w-V_\epsilon\,\partial_{tt}w+\tfrac{2(n-k)}{n-2k}\dot V_\epsilon\partial_t w\right]\\
&+S_2\left[\tfrac{k}{n-2k}(N-1) (V_\epsilon)^{-1}(\dot V_\epsilon)^2w+ (N-1)\tfrac{n-2k}{4k}V_\epsilon  w-V_\epsilon \Delta_\theta w\right.\\&\left.\qquad\quad-\tfrac{2k}{n-2k}(N-1)\dot V_\epsilon\partial_t w\right]\\
&+ S_3\left[\tfrac{k}{n-2k}p (V_\epsilon)^{-1} (\dot V_\epsilon)^2 w-p\tfrac{n-2k}{4k} V_\epsilon w+p\left( -V_\epsilon-\tfrac{2k}{n-2k}\dot V_\epsilon\right)\partial_t w\right.\\&\left.\qquad\quad-V_\epsilon e^{-2t}\Delta_z w\right].
\end{split}
\end{equation*}
Thus, using that $V_\epsilon$ is an exact solution to \eqref{equation-v} and formula \eqref{calculation-linearized2} for the linearization, we obtain that
\begin{equation*}
   L_\epsilon[w]=a^{\epsilon}_{0} w + a^{\epsilon}_{1} \partial_t w +a^{\epsilon}_{2}\partial_{tt} w+a^{\epsilon}_{3}\Delta_\theta w+a^{\epsilon}_{4} e^{-2t}\Delta_z w
\end{equation*}
for
\begin{equation}\label{a's}\begin{split}
&a^{\epsilon}_{0}=(k-q) c V_\epsilon^{q-1}-\tfrac{n-k}{n-2k}S_1V_\epsilon^{-1} \dot V_\epsilon^2 +\tfrac{k}{n-2k}(N-1)S_2V_\epsilon^{-1}\dot V_\epsilon^2\\&\quad+ \tfrac{k}{n-2k} p S_3 V_\epsilon^{-1}\dot V_\epsilon^2 -\tfrac{n-2k}{4k} S_1 V_\epsilon+(N-1)\tfrac{n-2k}{4k} S_2V_\epsilon\\&\quad-p\tfrac{n-2k}{4k}S_3V_\epsilon,\\
&a^{\epsilon}_{1}= \tfrac{2(n-k)}{n-2k}\dot V_\epsilon S_1-\tfrac{2k}{n-2k}(N-1)\dot V_\epsilon S_2+p\left( -V_\epsilon-\tfrac{2k}{n-2k}\dot V_\epsilon\right) S_3,\\
&a^{\epsilon}_{2}=-V_\epsilon S_1,\\
&a^{\epsilon}_{3}=-V_\epsilon S_2,\\
&a^{\epsilon}_{4}=- V_\epsilon S_3.
\end{split}\end{equation}
This completes the proof of the Lemma.

\label{lemma:indicial-origin} For each
 $j=0,1,\ldots$, there exist two indicial roots $\gamma_j^\pm$, given as solutions of $f_j(\gamma)=0$. These satisfy:
\begin{itemize}
\item $\gamma_0^\pm$ can be real or complex. If they are real and different, then
\begin{equation}\label{gamma0}0<\gamma_0^-<\tfrac{p}{2}<\gamma_0^+,\end{equation}
otherwise it holds
\begin{equation}\label{gamma00}\operatorname{Re} \gamma_0^\pm=\tfrac{p}{2}>0.\end{equation}
\item For $j\geq 1$, $\gamma_{j}^\pm$ are real numbers. In addition, we have the monotonicity
\begin{equation}\label{indicial-zero2}
\ldots\leq\gamma_2^-\leq \gamma_1^-< \operatorname{Re}\gamma_0^-\leq\tfrac{p}{2}\leq \operatorname{Re}\gamma_0^+<\gamma_1^+\leq \gamma_2^+\leq\ldots
\end{equation}
\item It holds 
\begin{equation}\label{gamma1}\gamma_1^-=-1.
\end{equation}
\end{itemize}

\label{prop:expression}
The operator $\mathcal L_\epsilon$ has the  following expression:
\begin{equation}\label{mathcalL}
\mathcal L_\epsilon[\varphi]=\mathcal A_0^\epsilon(r) \varphi +  \frac{\mathcal A_1^\epsilon(r)}{r}\partial_r  \varphi +\mathcal A_2^\epsilon(r)\partial_{rr} \varphi+\frac{\mathcal A_3^\epsilon(r)}{r^2}\Delta_\theta \varphi+\mathcal A_4^\epsilon(r) \Delta_z \varphi,
\end{equation}
 for some coefficients $\mathcal A^\epsilon_\ell(r)$, $\ell=0,1,2,3,4$,  satisfying
$$\mathcal A^\epsilon_2,\mathcal A^\epsilon_3,\mathcal A^\epsilon_4>0.$$

\label{prop:indicial}
For each $j=0,1,\ldots$, there exist two indicial roots $\chi_{j,\pm}^{(0)}$ for the operator $\mathcal L_\epsilon$ as $r\to 0$. These satisfy:
\begin{itemize}
\item $\chi_{0,\pm}^{(0)}$ can be real or complex. In the former case,
$$-\tfrac{n-4}{4}<\chi^{(0)}_{0,-}<\tfrac{p}{2}-\tfrac{n-4}{4}<\chi^{(0)}_{0,+},$$
 while in the latter, $\operatorname{Re} (\chi^{(0)}_{0,\pm})=\frac{p}{2}-\frac{n-4}{4}$.
\item For $j\geq 1$, $\chi_{j,\pm}^{(0)}$ are real numbers. In addition, we have the monotonicity
\begin{equation}\label{indicial-zero}
\begin{split}
\ldots\leq\chi_{2,-}^{(0)}\leq \chi_{1,-}^{(0)}< \operatorname{Re}(\chi_{0,-}^{(0)})&\leq\tfrac{p}{2}-\tfrac{n-4}{4}\\
&\leq \operatorname{Re}(\chi_{0,+}^{(0)})<\chi_{1,+}^{(0)}\leq \chi_{2,+}^{(0)}\leq\ldots
\end{split}
\end{equation}
\item It holds $\chi_{1,-}^{(0)}=-1-\frac{n-4}{4}$.
\end{itemize}

As $r\to\infty$, the picture is similar and, for each $j=0,1,\ldots$, there exist two indicial roots $\chi_{j,\pm}^{(\infty)}$ for  $\mathcal L_\epsilon$ which satisfy:
\begin{itemize}
\item For all $j$, $\chi_{j,\pm}^{(\infty)}$ are real numbers. In addition, we have the monotonicity
\begin{equation}\label{indicial-infinity0}
\begin{split}
\ldots\leq\chi_{2,-}^{(\infty)}\leq \chi_{1,-}^{(\infty)}< \chi_{0,-}^{(\infty)}&\leq-\tfrac{n-4}{4}+\tfrac{p(n-3)}{2(n-1)}\\
&\leq \chi_{0,+}^{(\infty)}<\chi_{1,+}^{(\infty)}\leq \chi_{2,+}^{(\infty)}\leq\ldots
\end{split}
\end{equation}
\item It holds
\begin{equation}\label{indicial-infinity-first}
-\tfrac{n-4}{4}+\tfrac{p}{2}>\chi_{0,-}^{(\infty)}=-\tfrac{n-4}{4}+\tfrac{p(n-3)}{2(n-1)}-\tfrac{\sqrt{4p+5p^2-5pn+pn^2-p^2n}}{2(n-1)}.
\end{equation}
\item For $j=1$,
\begin{equation}\label{chi1-}
\chi_{1,-}^{(\infty)}=-1-\alpha_0-\tfrac{n-4}{4}
\end{equation}
and
\begin{equation}
\label{chi1+}\chi_{1,+}^{(\infty)}>0.
\end{equation}
\end{itemize}

The indicial roots at the origin were calculated in  Subsection \ref{subsection:indicial-roots0}, taking into account that the relation \eqref{rewrite} introduces a shift of $\frac{n-4}{4}$ in the indicial roots between $L_\epsilon$ and $\mathcal L_\epsilon$.

We started studying the behavior at infinity  in  Subsection \ref{subsection:indicial-rootsinfty}. Full details of the proof will be  postponed until Section \ref{section:injectivity}. However, let us give here the main ideas:

We start with  the $j=0$ mode, that corresponds to radially symmetric solutions. The fundamental observation is that knowing  an exact solution for the non-linear ODE \eqref{ODE-sigma2}, one can produce radially symmetric solutions of its linearized equation using dilation invariance, as explained in  Remark \ref{remark:dilation-inv}. Thus we know precisely the behavior at infinity of a particular solution $\varphi_\sharp$, which agrees with the power $r^{-\alpha_0^\pm}$. The precise value of $\alpha_0^\pm$ was calculated in the paper \cite{Gonzalez-Mazzieri} and it is given by
\begin{equation}\label{alpha0pm}
\alpha_0^{\pm}=\frac{n-4}{4}-\frac{p(n-3)}{2(n-1)}\pm\frac{\sqrt{4p+5p^2-5pn+pn^2-p^2n}}{2(n-1)},
\end{equation}
(we denote $\alpha_0=\alpha_0^-$). From here we conclude that  $-\alpha_0^{\pm}$ are the two indicial roots for $j=0$.

Note also  that the expression inside the square root in formula \eqref{alpha0pm} is always positive in our range of $p$. This implies that, for all $j$, all the indicial roots  are real numbers.  Summarizing this discussion, we have shown \eqref{indicial-infinity0}.


We can also give explicit formulas for $j=1$. Using rotational invariance from Remark \ref{remark:rotation-invariance} one can find an explicit solution in the kernel for $j=1$, and this yields \eqref{chi1-}. Finally, to show \eqref{chi1+}, one just needs to check that
\begin{equation*}
-\tfrac{n-4}{4}+p\tfrac{n-3}{n-1}+1+\alpha_0>0,
\end{equation*}
which follows from simple algebra for $n\geq 5$.

\label{prop:compare-operators}
For functions supported in $\mathcal T_\varrho(\Lambda)$ that do not depend on the $z$ variable, we have that
\begin{equation}\label{compare-operators}\mathbb L'_\epsilon=\mathcal L'_\epsilon+\mathcal D,
\end{equation}
where $\mathcal D$ is a second order differential operator (at most) that satisfies, for functions of the form $\varphi=O(r^a)$ as $r\to 0$,
\begin{equation*}
\mathcal D \varphi=O(r^{a-2+\beta}),
\end{equation*}
for some $\beta>0$.

\label{remark:L0} The normalization $\mathbb L'_\epsilon$ behaves as:
\begin{itemize}
\item Away from the singularity, we have a usual uniformly elliptic, non-degenerate operator, independently of $\epsilon$.


\item Near the singularity set, $\mathbb L'_\epsilon$ is in the class of elliptic edge operators from \cite{Mazzeo:edge}, and it is modelled after $\mathcal L'_\epsilon$. In particular, it has constants indicial roots as $r\to 0$ (independent of $\epsilon$).
\end{itemize}

\label{def:holder-spaces}
The space $\mathcal C_0^{l,\alpha}(M \setminus \Lambda)$ is defined to be the set of all $u\in \mathcal C^{l,\alpha}(M\setminus \Lambda)$ for which the norm
\begin{equation*}
\|u\|_{\mathcal C^{l,\alpha}_0}=\|u\|_{\mathcal C^{l,\alpha}(M\setminus \mathcal T_{\rho/2})}+\sum_{j=0}^l\|\nabla^j u\|_{0,\alpha,0}^{\mathcal{T}}
\end{equation*}
is finite.

Now we consider a function $d_\Lambda$  behaving as the Fermi coordinate $r$ in a tubular neighborhood $\mathcal T_\rho$ of $\Lambda$ and a positive constant (say, identically one) away from the singular set. Then a function $u$ belongs to $\mathcal C_\mu^{l,\alpha}(M\setminus\Lambda)$ if and only if
\begin{equation*}
u=(d_\Lambda)^\mu \hat u \quad\text{for some}\quad \hat u\in \mathcal C^{l,\alpha}(M\setminus\Lambda).
\end{equation*}
This space is endowed with the natural norm
\begin{equation*}
\|u\|_{\mathcal C^{l,\alpha}_\mu}:=\|(d_\Lambda)^{-\mu} u\|_{\mathcal C^{l,\alpha}_0}.
\end{equation*}

The space $\mathcal C^{l,\alpha}_{\mu_1,\mu_2}(\mathbb{R}^N \setminus \{0\})$ consists of all functions $u$ for which the norm
\begin{equation*}
\|u\|_{\mathcal C^{l,\alpha}_{\mu_1,\mu_2}}=\sup_{B_R\setminus \{0\}}\|r^{-\mu_1}u\|_{l,\alpha,0}+\sup_{\mathbb{R}^N\setminus B_R}\|r^{-\mu_2}u\|_{l,\alpha,0}
\end{equation*}
is finite. The spaces  $\mathcal C^{l,\alpha}_{\mu_1,\mu_2}(\mathbb{R}^n \setminus \mathbb{R}^p)$ are defined similarly, in terms of the (global) Fermi coordinates  $(r,\theta,z)$ and the weights $r^{\mu_1}$, $r^{\mu_2}$.

Introduce a cutoff $\chi$ identically one on  $\mathcal T_{\rho/2}(\Lambda)$, vanishing outside $\mathcal T_{\rho}(\Lambda)$. Then
\begin{equation*}
\widetilde h_1:=  \widetilde {\mathbb L}'_\epsilon (\widetilde w\chi)=\chi   \widetilde {\mathbb L}'_\epsilon \widetilde w+[ \widetilde{\mathbb L}'_\epsilon,\chi]\widetilde w.
\end{equation*}
Thus if  inequality \eqref{not-so-easy} is true for $\widetilde w\chi$, it is also true for $\widetilde w$ by adding a compactly supported term.

\label{lemma:not-so-easy-preliminary}
If $\delta$ not an indicial root, for every solution $\omega(\tau)$ of \eqref{problem-K} supported on $(0,\infty)$ we have
\begin{equation}\label{not-so-easy-preliminary}
\|\omega\|_{L^2_\delta(d\tau)}\leq C\|\psi\|_{L^2_\delta(d\tau)}.
\end{equation}

\label{lemma:tau0}
Fix $\delta>0$ not an indicial root. Let $\omega(\tau)$ be a solution of \eqref{problem-Kj} supported on $\tau\in(\tau_0,\infty)$, $\tau_0\in\mathbb R$. Then
\begin{equation}\label{not-so-easy-s}
\|\omega\|_{L^2_\delta(d\tau)}\leq C\|\psi\|_{L^2_\delta(d\tau)},
\end{equation}
for a constant $C$ independent of $\omega$ and $\tau_0$.

The proof goes similarly to that of Lemma \ref{lemma:not-so-easy-preliminary}. First, in the case
$0<\delta<\delta_j$, one can repeat the proof line by line, noting that the additional term $-\int \omega^2e^{2\tau}e^{2\delta \tau}$ has the right sign and can be dropped while keeping the inequality.

The case $\delta>\delta_j$ is more delicate, since involves Bessel functions.  We can still write the solution to problem \eqref{problem-K} as
$$ \omega=\frac{1}{W}\left( B^+\int_{\tau}^{+\infty} B^- \psi - B^-\int_{\tau}^{+\infty} B^+ \psi \right)=:\frac{1}{W}(\omega_1+\omega_2),$$
where
\begin{equation*}
B_+(\tau):= K_{\delta_j}(e^{-\tau}),\quad
B_-(\tau):= I_{\delta_j}(e^{-\tau}),
\end{equation*}
where $I_{\delta_j},K_{\delta_j}$ are the modified Bessel functions of the second kind. Their asymptotic behavior is well known and, indeed, when $\tau\to +\infty$,
$B^+(\tau)\sim e^{{\delta_j} \tau}$ and $B^-(\tau)\sim e^{-{\delta_j} \tau}$. The  Wronskian $W$ is well known and has constant value (see \cite{Watson}, Chapter III, formula (80)).

We will give the proof for the term $\omega_1:=B_+ \int_\tau^\infty B_- \psi$. An analogous argument yields the estimate for $\omega_2$. First use integration by parts
\begin{equation*}\begin{split}
&\|\omega_1\|^2_{L^2_{\delta}(d\tau)}\\&= \int_{\tau_0}^{\infty} B_+(\tau)^2 \left( \int_{\tau}^\infty
B_-(\sigma) \psi(\sigma)\,d\sigma\right)^2 e^{2\tau\delta}\,d\tau\\
&=\int_{\tau_0}^\infty \partial_\tau \left( \frac{1}{2\delta+2\delta_j}e^{2\delta \tau +2\delta_j \tau}\right)e^{-2\delta_j \tau}B_+(\tau)^2\left( \int_{\tau}^\infty
B_-(\sigma) \psi(\sigma)\,d\sigma\right)^2\,d\tau\\&
=:J_1+J_2,
\end{split}\end{equation*}
where
\begin{equation*}
\begin{split}
J_1&=\frac{1}{\delta+\delta_j}\int_{\tau_0}^\infty e^{2\delta \tau}B_+(\tau)^2B_-(\tau)\psi(\tau)\int_\tau^\infty B_-(\sigma)\psi(\sigma)\,d\sigma \,d\tau\\&
=\frac{1}{\delta+\delta_j}\int_{\tau_0}^\infty e^{2\delta \tau}B_+(\tau)B_-(\tau)\psi(\tau) \omega_1(\tau)\,d\tau,
\end{split}
\end{equation*}
just nothing that $B_+(\tau)B_-(\tau)$ is a uniformly bounded positive function. Finally,  H\"older's inequality yields
\begin{equation*}
\begin{split}
J_1&\leq  \frac{C}{\delta+\delta_j} \left(\int_{\tau_0}^\infty \psi(\tau)^2e^{2\delta \tau}\,d\tau\right)^{1/2}\left(\int_{\tau_0}^\infty \omega_1(\tau)^2e^{2\delta \tau}\,d\tau\right)^{1/2}\\
& =\frac{C}{\delta+\delta_j}\|\psi\|_{L^2_{\delta}(d\tau)}\|\omega_1\|_{L^2_{\delta}(d\tau)}.
\end{split}\end{equation*}
 
On the other hand,
\begin{equation*}\begin{split}
J_2&= -\frac{1}{2\delta+2\delta_j}\int_{\tau_0}^\infty e^{2\delta \tau+2\delta_j \tau} \partial_\tau \left( e^{-2\delta_j \tau}B_+(\tau)^2\right)\int_\tau^\infty B_-(\sigma)\psi(\sigma)\,d\sigma \,d\tau \\
&= -\frac{1}{2\delta+2\delta_j}\int_{\tau_0}^\infty e^{2\delta \tau} \partial_\tau \log\left( e^{-2\delta_j \tau}B_+(\tau)^2\right)\omega_1(\tau)^2\,d\tau.
\end{split}
\end{equation*}
 
Calculate, for $s=e^{-\tau},$
\begin{equation*}
\begin{split}
\partial_\tau \log\left( e^{-2\delta_j \tau}B_+(\tau)^2\right)&=2\left[-\delta_j+\frac{\partial_\tau B_+(\tau)}{B_+(\tau)}\right]=2\left[-\delta_j-\frac{s\partial_s K_{\delta_j}(s)}{K_{\delta_j}(s)}\right]\\
&=
-2\frac{s^{1-\delta_j} \partial_s(s^{\delta_j} K_{\delta_j}(s))}{K_{\delta_j}(s)}\geq 0,
\end{split}\end{equation*}
using Property 3.71 in \cite{Watson} which implies  $\partial_s(s^{\delta_j} K_{\delta_j}(s))\leq 0$.
By the crucial hypothesis $\delta>0$, the term $J_2$ has a sign and can be dropped. From the estimate for $J_1$ we have that
$$\|\omega_1\|^2_{L^2_{\delta}(d\tau)}\leq C\|\psi\|^2_{L^2_{\delta}(d\tau)},$$
for functions supported in $(\tau_0,+\infty)$ but now this constant $C$ is independent of $\tau_0$, as desired.\\

\label{L1-injective}
The only solution $\varphi\in\mathcal C^{2,\alpha}_{\mu,0}(\mathbb R^n\setminus\mathbb R^p)$ of
\begin{equation}\label{equation50}
\mathcal L_1 \varphi=0\quad \text{in }\mathbb R^n\setminus\mathbb R^p
\end{equation}
is $\varphi\equiv 0$.

First remark that it is enough to study injectivity of the projected operators
\begin{equation*}
\mathcal L^{(0)}_j[\varphi]=\beta_0^{(0)} \varphi +  \frac{\beta_1^{(0)}}{r}\partial_r  \varphi +\beta_2^{(0)}\partial_{rr} \varphi-\lambda_j\frac{\beta_3^{(0)}}{r^2} \varphi+\beta_4^{(0)} \Delta_z \varphi=0.
\end{equation*}
Recalling the discussion in Section \ref{section:Fredholm}, this can be reduced to proving injectivity for each equation
\begin{equation}\label{eq:j}
\partial_{\tau\tau}\omega-\delta_j^2\omega-e^{-2\tau}\omega=0, \quad \text{for }\omega=\omega(\tau), \quad\tau\in\mathbb R, \quad j=0,1,\ldots
\end{equation}
under the assumption that $\omega$ has the behavior
\begin{equation*}
\omega(r)=\left\{\begin{split}
&O(r^{\updelta})\quad\text{as}\quad r\to 0,\\
&O(r^{-\frac{p}{2}+\frac{n-4}{4}}) \quad\text{as}\quad r\to\infty.
\end{split}\right.
\end{equation*}
Here we have defined
$$\updelta:=\mu-\tfrac{p}{2}+\tfrac{n-4}{4}>0.$$

Let us look then at equation \eqref{eq:j}. For any $j$, this is a Bessel ODE which has two linearly independent solutions, given by the modified Bessel functions of second kind $K_{\delta_j}(r)$ and $I_{\delta_j} (r)$ in the variable $r=e^{-t}$. Since the asymptotic behavior of the Bessel functions is well known, any solution with such behavior as $r\to 0$ cannot be bounded as $r\to\infty$, which is not possible because the choice of function space.

Any other solution to
\begin{equation}\label{eq:nondegeneracy}
\mathfrak L_{1,0}\widetilde w=0
\end{equation}
that decays to zero as  $t\to \infty$ must be a multiple of $\widetilde w_\sharp$.

\label{remark:rotation-invariance}
Notice first that  rotational invariance yields that
\begin{equation*}
\mathfrak L_1 (\partial_j U_1)=0, \quad j=1,\ldots,N.
\end{equation*}
Since $\partial_j = e_j \partial_r$, then $\varphi_\diamond:=\partial_r U_1$ belongs to the kernel of $\mathfrak L_{1,j}$ for each $j=1,\ldots,N$.
Moreover,
\begin{equation*}
\varphi_\diamond(r)\asymp
r^{-\frac{n-4}{4}-1}\quad\text{as}\quad r\to 0,
\end{equation*}
and
\begin{equation*}
\varphi_\diamond(r)\sim r^{-\alpha_0-\frac{n-4}{4}-1} \quad\text{as}\quad r\to\infty.
\end{equation*}
In particular, this shows \eqref{chi1-}.

